CSS = '<style id="radar-clean-workbench">\n:root{color-scheme:dark;--clean-bg:#090c12;--clean-card:#10141f;--clean-line:#283347;--clean-text:#edf2fa;--clean-muted:#a5b4ca}\nhtml,body{background:var(--clean-bg)!important;color:var(--clean-text)!important;font-family:"Microsoft YaHei UI","Microsoft YaHei","PingFang SC",sans-serif!important;font-size:15px;line-height:1.65}\nmain{background:linear-gradient(110deg,#101824,#0b1018)!important;color:var(--clean-text)!important}\nmain .pd-root{max-width:1480px;margin:0 auto;padding:20px 22px 36px;color:var(--clean-text)}\nmain section,main article,main .pd-panel,main .card{background:var(--clean-card)!important;border:1px solid var(--clean-line)!important;border-radius:14px!important;box-shadow:none!important;color:var(--clean-text)!important}\nmain .pd-panel{padding:18px 20px!important;margin-bottom:16px!important}\nmain h1{font-size:24px!important;line-height:1.4}main h2{font-size:19px!important}main h3{font-size:16px!important}main h1,main h2,main h3,main h4,main strong{color:var(--clean-text)!important}\nmain p,main li,main label{color:var(--clean-text)}main small,main .muted,main .pd-muted{color:var(--clean-muted)!important;font-size:13px!important}main a{color:#a8cfff}\nmain button,main input[type=submit],main input[type=button]{width:auto!important;max-width:100%;min-height:38px;padding:8px 16px!important;border:1px solid #354760!important;border-radius:9px!important;background:#182538!important;color:#f0f5ff!important;font:inherit;cursor:pointer}\nmain button:hover{background:#233650!important}main input,main select,main textarea{background:#0c121c!important;border:1px solid #344158!important;border-radius:8px!important;color:#edf2fa!important;padding:9px 12px;font:inherit}main input::placeholder{color:#95a5ba!important}\nmain table{width:100%;border-collapse:collapse!important;background:#10141f!important;color:#edf2fa!important;font-size:14px!important;line-height:1.55!important;font-variant-numeric:tabular-nums}\nmain th{background:#141e2c!important;color:#bccde4!important;font-size:12px!important;font-weight:600!important;letter-spacing:.02em;text-align:left;padding:12px 14px!important;border-bottom:1px solid #354158!important;white-space:nowrap}\nmain td{background:transparent!important;border:0!important;border-bottom:1px solid #222d3e!important;padding:14px!important;vertical-align:middle;overflow-wrap:anywhere}\nmain tbody tr{background:#10141f!important}main tbody tr:nth-child(even){background:#121925!important}main tbody tr:hover{background:#1b293c!important}\nmain td:first-child{min-width:135px;font-weight:600}main td:last-child{white-space:nowrap}main td small{display:inline-block;margin-top:4px}\nmain details{margin:12px 0}main summary{cursor:pointer;color:#bdd6f5;padding:9px 0}main :focus-visible{outline:2px solid #86baff!important;outline-offset:3px}\nmain [style*="background: #fff"],main [style*="background:#fff"],main [style*="background-color: #fff"],main [style*="background-color:#fff"]{background:#10141f!important;color:#edf2fa!important}\nmain .pd-note,main .notice,main .alert{background:#132131!important;color:#cddcee!important;border-color:#34475e!important;border-radius:8px!important;padding:12px 16px!important}\n#fusion-data-freshness{border-left:3px solid #e0ad4f!important}#fusion-data-freshness p{margin:6px 0!important;font-size:13px!important}\nmain *{scrollbar-width:thin;scrollbar-color:#43516a #10141f}main ::-webkit-scrollbar{width:7px;height:7px}main ::-webkit-scrollbar-track{background:#10141f}main ::-webkit-scrollbar-thumb{background:#43516a;border-radius:8px}\n@media(max-width:800px){main .pd-root{padding:12px 10px 24px}main .pd-panel{padding:14px!important}main table{font-size:13px!important}main td,main th{padding:10px!important}main h1{font-size:21px!important}}\n</style>'

CSS += '<style id="radar-layout-fix-v2">\nhtml:root{--pd-bg:#090d14;--pd-card:#10141f;--pd-line:#293447;--pd-text:#edf2fa;--ths-panel:#10141f;--ths-line:#293447;--ths-text:#edf2fa}\nhtml body main{background:#0c121c!important;color:#edf2fa!important}\nhtml body main .pd-root{max-width:1480px;padding:0 8px 24px;font-size:15px}\nhtml body main .pd-root header.pd-heading{position:static!important;top:auto!important;z-index:auto!important;display:flex!important;grid-template-columns:none!important;grid-template-rows:none!important;height:auto!important;min-height:64px!important;padding:12px 0 18px!important;margin:0!important;background:transparent!important;box-shadow:none!important;align-items:center!important;justify-content:space-between!important;flex-wrap:wrap!important}\nhtml body main .pd-root .pd-heading>div{flex:1 1 auto!important;grid-area:auto!important}\nhtml body main .pd-root #pd-refresh{width:112px!important;flex:0 0 112px!important;grid-area:auto!important;align-self:center!important;margin:0!important;font-size:14px!important}\nhtml body main .pd-root .pd-panel,html body main .pd-root .card{background:#10141f!important;border:1px solid #293447!important;border-radius:14px!important;color:#edf2fa!important;padding:18px 20px!important}\nhtml body main .pd-root table.pd-table{background:#10141f!important;border-collapse:separate!important;border-spacing:0!important;font-size:14px!important}\nhtml body main .pd-root .pd-table tbody tr td{background:#10141f!important;color:#e8eef8!important;border-bottom:1px solid #253043!important;padding:12px 14px!important;line-height:1.65!important;font-weight:400}\nhtml body main .pd-root .pd-table tbody tr:nth-child(even) td{background:#121925!important}\nhtml body main .pd-root .pd-table tbody tr:hover td{background:#1b283a!important}\nhtml body main .pd-root .pd-table thead th{background:#172131!important;color:#bccde4!important;font-size:13px!important;border-bottom:1px solid #354359!important;z-index:5!important;padding:13px 14px!important;line-height:1.6!important}\nhtml body main .pd-root .pd-table thead th:first-child{z-index:6!important}\nhtml body main .pd-root .pd-table td:first-child{z-index:1!important;box-shadow:none!important}\nhtml body main .pd-root .pd-table td.pd-base{box-shadow:inset 2px 0 #3c526e!important}\nhtml body main .pd-root .pd-table small{display:block!important;font-size:12px!important;font-weight:400!important;color:#a9b9cd!important;margin-top:3px!important}\nhtml body main .pd-root .pd-table .pd-up{color:#ff7887!important}html body main .pd-root .pd-table .pd-down{color:#52d9ac!important}\nhtml body main .pd-root .pd-table-wrap{border:1px solid #293447;border-radius:10px;max-height:66vh;isolation:isolate}\nhtml body main .pd-root .pd-data-state,html body main .pd-root .pd-note{background:#121e2d!important;border:1px solid #2b3c52!important;color:#c5d3e6!important;border-radius:9px!important;padding:10px 14px!important;font-size:13px!important}\nhtml body .focus-nav{background:#0d121c!important;border-color:#263247!important}\nhtml body .focus-nav .focus-nav-brand{background:#141e2d!important;box-shadow:none!important;border:1px solid #293b54!important}\nhtml body .focus-nav .focus-nav-section,html body .focus-nav .focus-nav-section summary{background:#101722!important;border-color:#273348!important}\nhtml body .focus-nav a{border-radius:7px}\nhtml body main #fusion-data-freshness{background:#111a27!important;border-left:3px solid #d7a34d!important}\nhtml body main h2{margin-top:0!important}html body main input[type=search]{min-width:260px;max-width:100%}\n@media(max-width:800px){html body main{padding:14px 10px!important}html body main .pd-root{padding:0}html body main .pd-root .pd-panel{padding:14px!important}html body main .pd-root .pd-table{min-width:850px}html body main .pd-root header.pd-heading{gap:10px!important}}\n</style>'
